data.text:
{
  "situation": "OpCo's NOC reports that its customer-care chatbot showed one customer another subscriber's billing address and recent call records; the account-lookup tool has been disabled, logs preserved and the DPA notified, and OpCo asks TDRA (REG) to confirm any reporting expectation or deadline for subscriber-data disclosures. I do not know how many subscribers were exposed, whether the chatbot or its vendor retains the data, why the tool returned another subscriber's record, or whether TDRA, the DPA or the new Federal Authority for AI and Data owns subscriber-breach notification.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "S2: OpCo customer-care chatbot disclosed another subscriber's billing address and recent call records (subscriber information) - regulatory incident record"
      },
      "inject_refs": ["S2-MSG04", "S2-I1"],
      "rationale": {
        "observation": "NOC reports the support chatbot showed a customer another subscriber's billing address and recent call records; the tool is disabled, logs preserved and the DPA notified.",
        "rule": "Subscriber Information expressly includes address and call records (CPR 2.1.31), and the TDRA may direct remedies in the course of handling complaints and disputes (CPR 26.11).",
        "inference": "A TDRA incident record is needed to track the disclosure, the licensee's remediation and any regulatory remedy."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0028",
          "quote": "name, address, bank account details, credit card details, service usage details, call records, message records"
        },
        {
          "chunk_id": "UAE-TDRA-CPR-2#0377",
          "quote": "or to implement any other remedy deemed reasonable and appropriate by the TDRA."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Written report on the chatbot subscriber-information disclosure: data fields and number of subscribers exposed, how the account-lookup returned another subscriber's record, timeline, whether the chatbot provider retained the data, remedial steps and status of the affected subscriber's complaint"
      },
      "inject_refs": ["S2-MSG04", "S2-I1"],
      "rationale": {
        "observation": "OpCo asks TDRA to confirm a reporting expectation for subscriber-data disclosures and has so far provided only NOC's notification.",
        "rule": "Article 30 of the Executive Order lets the Authority issue a notification requiring a contravening party to submit specified documents or information.",
        "inference": "TDRA should formally require the licensee's account of the disclosure rather than rely on the initial notification."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-EXEC#0039",
          "quote": "the Authority may, for the purposes of the exercising its functions pursuant to the Federal Law by Decree and this Executive Order, issue a notification, where required, to the contravening party to submit to the Authority any documents or information"
        },
        {
          "chunk_id": "UAE-TDRA-CPR-2#0028",
          "quote": "name, address, bank account details, credit card details, service usage details, call records, message records"
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_audit",
      "params": {
        "of": "NOC",
        "topic": "Testing and change records for the customer-care chatbot account-lookup tool: pre-deployment privacy and security testing, access-control and scoping design, results of the disable_tool and restore_scope test runs, and log retention"
      },
      "inject_refs": ["S2-MSG04", "S2-FB01", "S2-FB02"],
      "rationale": {
        "observation": "NOC reports the account-lookup tool was disabled and then restored to an own_account scope, with twin metrics of leak_count 0 and benign_success_rate 1.0.",
        "rule": "Article 30 permits the Authority to require a contravening party to submit documents or information specified in a notification.",
        "inference": "The testing and change records are needed to establish whether the fix is verified and whether comparable chatbot tools carry the same defect."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-EXEC#0039",
          "quote": "the Authority may, for the purposes of the exercising its functions pursuant to the Federal Law by Decree and this Executive Order, issue a notification, where required, to the contravening party to submit to the Authority any documents or information"
        }
      ]
    },
    {
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "to": "NOC",
        "direction": "Keep the chatbot's account-lookup function disabled or restricted to the authenticated customer's own account, preserve all logs and chatbot conversation records, and do not re-enable any wider lookup scope until TDRA has the testing evidence and confirms"
      },
      "inject_refs": ["S2-MSG04", "S2-FB01", "S2-FB02"],
      "rationale": {
        "observation": "The tool has been disabled and re-scoped, but the incident is unresolved and it is not yet known whether the exposure was isolated.",
        "rule": "Upon recognition of a contravention, the Authority may issue directives to the Licensee to oblige him or abstain him from any activity specified in the directives.",
        "inference": "A direction locks in the interim safeguard and prevents re-enablement before the defect is fully understood."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-EXEC#0039",
          "quote": "Upon recognition of that contravention, the Authority may issue directives to the Licensee to oblige him or abstain him from any activity as may be specified in the directives."
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "NOC",
        "content": "TDRA acknowledges OpCo's Day 1 notification and has opened a regulatory incident record on the chatbot disclosure of another subscriber's billing address and call records. TDRA requires the written report and the testing/change records requested separately. On OpCo's question: the retrieved licence texts state no TDRA reporting deadline for subscriber-data disclosures; TDRA will confirm the reporting expectation in writing and expects all logs and evidence to be preserved meanwhile."
      },
      "inject_refs": ["S2-MSG04"],
      "rationale": {
        "observation": "OpCo asks REG to confirm any TDRA reporting expectation or deadline for subscriber-data disclosures, saying the retrieved licence texts do not specify one.",
        "rule": "Licence 9.2.1 requires a Code of Practice covering privacy of customer information but states no disclosure-reporting deadline.",
        "inference": "TDRA should acknowledge and set expectations without inventing a deadline that no retrieved text supports."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0054",
          "quote": "b) privacy of Customer information"
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "OpCo must maintain a published Code of Practice that covers, at a minimum, privacy of customer information and handling of complaints; the chatbot disclosure engages that licence duty now.",
      "inject_refs": ["S2-MSG04", "S2-I1"],
      "rationale": {
        "observation": "NOC itself characterises the disclosure as a failure of the privacy-of-customer-information and complaint-handling commitments in its customer Code of Practice under Licence 9.2.1.",
        "rule": "Licence 9.2.1 requires the Code of Practice to contain information on privacy of Customer information and handling of complaints.",
        "inference": "The licensee must comply with those Code commitments, and their breach grounds regulatory action."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0054",
          "quote": "b) privacy of Customer information"
        },
        {
          "chunk_id": "UAE-LIC-2-2026#0054",
          "quote": "9.2.1 The Licensee shall prepare and publish a Code of Practice for the Licensee’s Customers"
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "obligation",
      "statement": "OpCo must treat and handle the affected subscriber's grievance about the chatbot disclosure as a Consumer Complaint under the CPR regime.",
      "inject_refs": ["S2-MSG04", "S2-I1"],
      "rationale": {
        "observation": "A customer posted a screenshot showing another subscriber's billing address and recent call records exposed by OpCo's support chatbot.",
        "rule": "CPR 2.1.7 defines a Consumer Complaint as any correspondence or communication from a Subscriber expressing dissatisfaction or grievance with the licensee's handling of the Subscriber's account.",
        "inference": "The affected subscriber's grievance is a Consumer Complaint that OpCo must handle and answer through the consumer complaint procedure."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0008",
          "quote": "any correspondence or communication registered by any reasonable means at any place authorised by the Licensee for such purposes, from a Subscriber expressing dissatisfaction or grievance"
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "No retrieved UAE text sets a deadline or a defined reporting expectation for a licensee to notify TDRA of a subscriber-information disclosure - the licence only requires a Code of Practice containing privacy of customer information - so TDRA cannot confirm the deadline OpCo asks about.",
      "inject_refs": ["S2-MSG04"],
      "rationale": {
        "observation": "OpCo asks TDRA to confirm any reporting expectation or deadline for subscriber-data disclosures, stating the retrieved licence texts do not specify one.",
        "rule": "Licence 9.2.1 requires a Code of Practice containing privacy of customer information but states no disclosure-reporting duty or timeline.",
        "inference": "The absence of a disclosure-reporting deadline is a regulatory gap that should be closed by a TDRA rule, licence condition or guidance."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0054",
          "quote": "b) privacy of Customer information"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "NL-AP-CHATBOT-2024#0000",
          "quote": "Recently, the Dutch Data Protection Authority (Dutch DPA) has received a number of notifications of data breaches caused by employees sharing personal data of, for example, patients or customers with a chatbot that uses artificial intelligence."
        },
        {
          "chunk_id": "CA-CRTC-2025-225#0024",
          "quote": "The information that TSPs are required to provide in a major service outage notification should be sufficient for the relevant government authorities to address the causes and impacts of an outage"
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "overlap",
      "statement": "Ownership of subscriber-data breach notification and oversight is not settled among TDRA (licence and consumer protection), the DPA under the PDPL, and the new Federal Authority for AI and Data, so the same chatbot disclosure may fall to more than one body.",
      "inject_refs": ["S2-MSG04", "S2-I1"],
      "rationale": {
        "observation": "NOC states the DPA has been notified while simultaneously asking TDRA to confirm its own reporting expectation; no single recipient is identified for licensees.",
        "rule": "The PDPL Implementing Regulations, including breach notifications, have still not been issued and no supervisory authority has been unambiguously designated for private-sector oversight.",
        "inference": "Without a designated owner, notification duties for subscriber-data disclosures may be duplicated across institutions or fall between them."
      },
      "evidence": [
        {
          "chunk_id": "UAE-FAAID-2026#0001",
          "quote": "no supervisory authority has been unambiguously designated for private sector oversight, and businesses have been operating in a state of prolonged regulatory uncertainty"
        },
        {
          "chunk_id": "UAE-FAAID-2026#0001",
          "quote": "The expectation across the market is that the Authority will take ownership of finalising those regulations and bring meaningful enforcement of the PDPL within its mandate."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "NL-AP-CHATBOT-2024#0000",
          "quote": "the Dutch Data Protection Authority (Dutch DPA) has received a number of notifications of data breaches caused by employees sharing personal data of, for example, patients or customers with a chatbot that uses artificial intelligence."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No retrieved UAE text sets requirements for automated or AI customer-service tools that access subscriber information - for example authentication before any lookup, limiting responses to the requesting subscriber's own account, and privacy testing before deployment.",
      "inject_refs": ["S2-MSG04", "S2-I1", "S2-FB01", "S2-FB02"],
      "rationale": {
        "observation": "The chatbot served another subscriber's billing address and call records, and was corrected only by disabling the tool and re-scoping it to own_account.",
        "rule": "The closest UAE text is Licence 9.2.1, which requires a Code of Practice containing privacy of Customer information, but sets no technical or testing requirements for automated channels.",
        "inference": "A rule is needed on authentication, data scoping and pre-deployment testing for AI/chatbot tools that can retrieve Subscriber Information."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0054",
          "quote": "b) privacy of Customer information"
        },
        {
          "chunk_id": "UAE-TDRA-CPR-2#0028",
          "quote": "name, address, bank account details, credit card details, service usage details, call records, message records"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "NL-AP-CHATBOT-2024#0000",
          "quote": "The Dutch DPA also received a notification from a telecom company, where an employee had entered a file with addresses of customers, among other things, into an AI chatbot."
        },
        {
          "chunk_id": "US-CFR-47-64-2010#0001",
          "quote": "a telecommunications carrier must authenticate the customer without the use of readily available biographical information, or account information."
        }
      ]
    },
    {
      "type": "share",
      "to": ["DPA", "CSC"],
      "inject_refs": ["S2-MSG04", "S2-I1"],
      "statement": "Passing to DPA and CSC: OpCo's customer-care chatbot showed one subscriber another subscriber's billing address and recent call records (subscriber information), the tool has been disabled, logs preserved and the DPA notified. TDRA has opened a regulatory incident record; the PDPL breach-notification position and any cyber-security angle are outside the UAE texts retrieved by TDRA."
    },
    {
      "type": "insufficient_evidence",
      "statement": "Whether TDRA has a reporting expectation or deadline for a licensee to notify subscriber-data disclosures is not answered by the retrieved excerpts; none states an hour or day figure for such a report.",
      "inject_refs": ["S2-MSG04"],
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0054",
          "quote": "9.2.1 The Licensee shall prepare and publish a Code of Practice for the Licensee’s Customers"
        }
      ]
    }
  ]
}

{
  "situation": "OpCo's log review and the TDRA/DPA scope reports show that a vendor update silently widened OpCo's customer-care chatbot retrieval scope from 'own account' to 'all accounts', causing roughly 1,200 sessions over three days to disclose other subscribers' billing addresses and call records, with the model and chat logs hosted outside the UAE; the account-lookup tool has been disabled and re-enabled limited to the caller's own account. I do not have the definitive set of affected subscribers, confirmation that the offshore chat logs are secured or deleted, any stated regulatory reporting deadline, or the forensic/change-control records that are still being assembled.",
  "claims": [
    {
      "type": "action",
      "verb": "request_ioc",
      "params": {"from": "NOC"},
      "inject_refs": ["S2-I2", "S2-MSG17"],
      "rationale": {
        "observation": "OpCo's log review and the TDRA scope report identify a vendor update that changed the bot's retrieval scope and ~1,200 sessions exposing subscriber data, with audit logs and the vendor update package preserved.",
        "rule": "The National Cybersecurity Strategy provides for active monitoring and cross-agency intelligence sharing as part of the national incident response capability.",
        "inference": "CSC should obtain the retrieval-scope indicators and the preserved vendor update package and logs to characterise this AI-system failure and share actionable indicators with other agencies."
      },
      "evidence": [
        {"chunk_id": "UAE-CYBER-STRATEGY-2019#0003", "quote": "Single Point of Contact Advisories to protect against threats Active Monitoring for cyber threats Cross-Agency Intelligence Sharing"}
      ]
    },
    {
      "type": "action",
      "verb": "issue_advisory",
      "params": {
        "audience": "operators",
        "content": "Advisory to UAE operators on securing AI/ML customer-service assistants: this incident arose when a vendor update widened a chatbot's data-retrieval scope from 'own account' to 'all accounts', exposing other subscribers' billing addresses and call records over ~1,200 sessions with the model and chat logs hosted outside the UAE. Operators should enforce least-privilege retrieval scoping, treat AI/model and retrieval-scope changes as controlled changes subject to verification before release, apply access controls and monitoring to AI/ML inference, and preserve AI and lookup logs for incident response. Align AI adoption with the National Cyber Security Policy for Artificial Intelligence."
      },
      "inject_refs": ["S2-I2", "S2-MSG13"],
      "rationale": {
        "observation": "The disclosure was caused by a vendor update that silently widened the AI assistant's retrieval scope, and the vendor hosts the model and chat logs abroad.",
        "rule": "The National Cyber Security Policy for AI requires managing supply chain risks, controlling system changes, enforcing access controls, and operating an AI monitoring and response framework.",
        "inference": "An operator-facing advisory is the CSC instrument to propagate these AI security requirements to other telecom operators running similar customer-service assistants before the same vendor pattern recurs."
      },
      "evidence": [
        {"chunk_id": "UAE-CSC-AI-POLICY#0000", "quote": "It focuses on identifying, assessing, and mitigating unique risks, managing supply chain risks, controlling system changes, and ensuring compliance with privacy regulations."},
        {"chunk_id": "UAE-CSC-AI-POLICY#0001", "quote": "Requirements to establish an effective AI/ML security analytics framework for real-time threat detection and predictive insights."}
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "DPA",
        "content": "CSC notes for the DPA breach file: the vendor hosts the chatbot model and chat logs outside the UAE, so subscriber billing addresses and call records disclosed in the ~1,200 sessions may have been accessible or transferred outside UAE jurisdiction. Please ensure the formal report and any preservation or deletion requests cover the offshore chat logs and the vendor update package."
      },
      "inject_refs": ["S2-I2", "S2-MSG13"],
      "rationale": {
        "observation": "The DPA reported that the vendor hosts the model and the chat logs outside the UAE while the disclosed records are subscriber billing addresses and call records.",
        "rule": "The AI security policy requires managing supply chain risks and ensuring compliance with privacy regulations across the AI/ML lifecycle.",
        "inference": "The cross-border hosting element is material to the DPA's breach notification and should be explicitly captured in the formal report and preservation steps."
      },
      "evidence": [
        {"chunk_id": "UAE-CSC-AI-POLICY#0000", "quote": "It focuses on identifying, assessing, and mitigating unique risks, managing supply chain risks, controlling system changes, and ensuring compliance with privacy regulations."}
      ]
    },
    {
      "type": "obligation",
      "statement": "As the national cyber security authority in this incident, CSC must enable a swift, coordinated national response and cross-agency information sharing for the AI-vendor subscriber-data disclosure, coordinating with REG, DPA and NOC.",
      "inject_refs": ["S2-MSG17", "S2-MSG13"],
      "rationale": {
        "observation": "A telecom operator incident involving an AI vendor and offshore data has been reported across REG, DPA and NOC channels with scope, cause and containment established.",
        "rule": "The National Cybersecurity Strategy aspires to a robust National Cyber Incident Response plan enabling swift coordinated response and cross-agency information sharing.",
        "inference": "CSC holds the coordination role for this cross-institution AI incident and should drive the shared response rather than leave scope fragmented across agencies."
      },
      "evidence": [
        {"chunk_id": "UAE-CYBER-STRATEGY-2019#0003", "quote": "Establishing a robust National Cyber Incident Response plan to enable swift and coordinated response to cyber incidents in the UAE"}
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "No UAE text retrieved specifies a deadline for reporting subscriber-data disclosures made through AI systems; REG itself notes the licence texts do not specify a TDRA reporting expectation or deadline for such disclosures.",
      "inject_refs": ["S2-MSG04"],
      "rationale": {
        "observation": "REG reported that OpCo asked it to confirm the TDRA reporting expectation or deadline for subscriber-data disclosures, which the retrieved licence texts do not specify.",
        "rule": "The Consumer Protection Regulations define Subscriber Information broadly but the retrieved text sets no disclosure-reporting deadline.",
        "inference": "Without a stated deadline, reporting timing for AI-driven subscriber-data disclosures is left to interpretation, risking delay across operator, regulator and authority channels."
      },
      "evidence": [
        {"chunk_id": "UAE-TDRA-CPR-2#0028", "quote": "any personal data relating to a specific Subscriber and includes, but is not limited to, that Person’s: name, address, bank account details, credit card details, service usage details, call records"}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-DA-24-892#0036", "quote": "a comprehensive Breach response plan that will enable AT&T to fulfill its Breach notification obligations under applicable laws"},
        {"chunk_id": "US-CFR-47-64-2010#0001", "quote": "Telecommunications carriers must notify customers immediately whenever a password, customer response to a back-up means of authentication for lost or forgotten password, online account, or address of record is created or changed."}
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No retrieved UAE text explicitly governs the security of AI model and retrieval-scope updates supplied by third-party vendors for telecom customer data; the AI security policy states governance and supply-chain principles but no operative rule for vetting vendor model changes before they touch subscriber data.",
      "inject_refs": ["S2-I2", "S2-MSG17"],
      "rationale": {
        "observation": "The leak began immediately after a vendor update changed the bot's retrieval scope, with the vendor hosting model and logs abroad.",
        "rule": "The AI policy requires supply chain risk management and controlling system changes, but the retrieved text is a policy summary without an operative pre-release control rule.",
        "inference": "A concrete rule requiring operator verification and authority notification of vendor AI changes affecting data scope is missing, leaving this class of change unregulated."
      },
      "evidence": [
        {"chunk_id": "UAE-CSC-AI-POLICY#0000", "quote": "It focuses on identifying, assessing, and mitigating unique risks, managing supply chain risks, controlling system changes, and ensuring compliance with privacy regulations."}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-DA-24-892#0036", "quote": "the exercise of due diligence in selecting Vendors capable of reasonably safeguarding Covered Data"},
        {"chunk_id": "US-CRS-CROWDSTRIKE#0003", "quote": "The risk is that when the vendor releases a software update over the internet, it can affect many computers and many entities at once, including public safety agencies."}
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_owner",
      "statement": "It is not clear from the retrieved texts which authority owns approval and verification of third-party AI model or retrieval-scope changes in the telecom sector, with AI governance under CSC and subscriber-info protection under TDRA/REG giving no single named owner.",
      "inject_refs": ["S2-MSG17", "S2-MSG13"],
      "rationale": {
        "observation": "The vendor update crossed AI governance (CSC AI policy) and telecom subscriber-data protection (TDRA/REG) without a designated approval owner, and the change was only caught after exposure.",
        "rule": "The AI policy requires a governance framework covering secure design, development and operation through enforceable policies and procedures.",
        "inference": "A named owner for vendor AI change control in telecom would have created a pre-release checkpoint, so this is a no-owner gap the incident exposes."
      },
      "evidence": [
        {"chunk_id": "UAE-CSC-AI-POLICY#0000", "quote": "Requirements to establish a robust governance framework for AI/ML systems, ensuring their secure design, development, and operation through comprehensive, enforceable policies and procedures."}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-DA-24-892#0024", "quote": "which included encryption requirements, access control requirements, and network oversight requirements."}
      ]
    },
    {
      "type": "share",
      "to": ["REG"],
      "inject_refs": ["S2-I2", "S2-MSG17"],
      "statement": "Passing to REG the cross-border dimension of the case: the vendor hosts the chatbot model and chat logs outside the UAE, so the subscriber billing addresses and call records disclosed in ~1,200 sessions may sit in offshore logs. This is relevant to the TDRA reporting and to any scope, preservation or vendor-change-control expectations REG is confirming."
    },
    {
      "type": "insufficient_evidence",
      "statement": "The retrieved excerpts do not answer what TDRA reporting expectation or deadline applies to this subscriber-data disclosure; no UAE text stating such a deadline is available to me.",
      "inject_refs": ["S2-MSG04"],
      "evidence": []
    }
  ]
}

{
  "situation": "I know that OpCo's customer-care chatbot disclosed other subscribers' billing addresses and call records in about 1,200 sessions over three days, starting immediately after a vendor update widened its retrieval scope from 'own account' to 'all accounts', that the vendor hosts the model and chat logs outside the UAE, and that TDRA, the DPA Bureau and CSC have each opened records, require the written report, testing and change records and log preservation, and confirm that no UAE deadline figure applies. I do not have the distinct number of affected data subjects, the vendor update package, model/configuration version identifiers or retrieval audit logs, and I cannot decide the cross-border transfer question or unilaterally change the model while the regulators require changes to be held as controlled changes pending verification.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S2-MSG20", "S2-MSG26", "S2-MSG33", "S2-MSG34"],
      "rationale": {
        "observation": "The Bureau and TDRA repeatedly require OpCo to keep and produce the chatbot and lookup audit logs, the vendor update record, model and configuration version identifiers and the change/testing records.",
        "rule": "Article 7(1) of the PDPL requires the Controller to take technical and organisational measures to protect Personal Data and to ensure it is not breached, destroyed, altered or tampered with.",
        "inference": "Active preservation of the personal data involved and of the incident evidence is both the security measure the PDPL requires and the precondition for the reports the regulators demand."
      },
      "evidence": [
        {"chunk_id": "UAE-PDPL#0021", "quote": "Take appropriate technical and organizational measures to implement the necessary standards to protect and secure Personal Data in order to preserve its confidentiality and privacy, and to ensure that it is not breached, destroyed, altered or tampered with"}
      ]
    },
    {
      "type": "action",
      "verb": "restore_scope",
      "params": {"scope": "own_account"},
      "inject_refs": ["S2-MSG16", "S2-MSG33", "S2-FB36"],
      "rationale": {
        "observation": "The disclosure was caused by the vendor update widening the chatbot's retrieval scope to 'all accounts'; CSC and TDRA require the corrected own-account scope to stay enforced as a controlled change pending verification.",
        "rule": "Article 7(1) of the PDPL requires measures to be proportionate to the nature, scope and purposes of processing and to the risks to the confidentiality and privacy of the Data Subject's Personal Data.",
        "inference": "Limiting the chatbot's retrieval to the caller's own account is the minimum technical measure that stops further disclosure while keeping the tool usable, and must remain enforced rather than re-widened."
      },
      "evidence": [
        {"chunk_id": "UAE-PDPL#0021", "quote": "taking into account the nature, scope and purposes of processing and the possibility of risks to the confidentiality and privacy of the Data Subject's Personal Data."}
      ]
    },
    {
      "type": "obligation",
      "statement": "OpCo must keep the corrected 'own account' chatbot retrieval scope enforced and treat any further scope or model change as a controlled change pending verification, with the vendor update package, model/configuration version identifiers and change/testing records preserved.",
      "inject_refs": ["S2-MSG16", "S2-MSG20", "S2-MSG26", "S2-MSG28"],
      "rationale": {
        "observation": "CSC, TDRA and the Bureau all direct that the corrected scope stay enforced and that further scope or model changes be held as controlled changes pending verification, with the vendor update treated as a possible supply-chain compromise.",
        "rule": "Article 21(1) of the PDPL requires the Controller, before carrying out processing, to evaluate the impact of proposed processing operations when using modern technologies that pose a high risk.",
        "inference": "Any re-widening of retrieval scope or replacement model must be impact-assessed and independently verified before it is deployed, so it cannot be treated as an ordinary operational change."
